output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in very narrow single-file aisles with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartInSingleFileShelfAisle": {
          "and": [
            "hasCart",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileShelfAisle"
    }
  },
  {
    "id": "no_push_cart_into_single_file_aisle",
    "text": "A shopper must not push a cart northward from a wide aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "cartless_motion_only_in_pedestrian_zones",
    "text": "After leaving the entrance, moving without a cart is only allowed in pedestrian-only single-file aisles or at their cart-parking mouths.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entryCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartlessAllowedArea": {
          "or": [
            "singleFileShelfAisle",
            "cartParkingMouth",
            "entryCartArea"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": "cartlessAllowedArea"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_cartless_single_file_selection",
    "text": "If a shopper selects an item while cartless in a single-file shelf aisle, they are obliged to retrieve a cart afterward.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartlessSingleFileSelection": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "cartRetrieved": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessSingleFileSelection",
      "discharge": "cartRetrieved"
    }
  },
  {
    "id": "retrieve_cart_after_exiting_single_file_on_foot",
    "text": "A shopper who exits a single-file shelf aisle without a cart must pick the cart back up at the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "exitSingleFileOnFoot": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "S"
            ]
          },
          "post": "cartParkingMouth"
        },
        "cartRetrievedAtMouth": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "exitSingleFileOnFoot",
      "discharge": "cartRetrievedAtMouth"
    }
  },
  {
    "id": "cart_required_for_tight_bay_shelf_interactions",
    "text": "Shelf interactions in tight side bays or end-cap areas require having the cart with you.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "tightBayOrEndcapShelfZone": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    2
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "tightBayOrEndcapShelfZone",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_carts_only_in_broad_unobstructed_aisles",
    "text": "Carts may only be set down in broad unobstructed aisle cells, not in shelf-adjacent or constricted spaces.",
    "abstraction": {
      "state_properties": {
        "broadUnobstructedAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "putDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "putDownCart",
          {
            "not": "broadUnobstructedAisle"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_aisles_are_out_and_back",
    "text": "Entering a single-file shelf aisle on foot creates an obligation to return south to the aisle mouth before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "returnToMouthFromSingleFile": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "S"
            ]
          },
          "post": "cartParkingMouth"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "returnToMouthFromSingleFile"
    }
  }
]
